SELECT DISTINCT cc.id AS id, cc.company_name AS companyName, cc.open_id AS openId, cc.tax_number AS taxNumber, ci.customer_name AS customerName, ci.contact_name AS contactName, ci.phone AS phone, cs.sale_owner_user_name AS saleOwnerUserName, cs.butler_owner_user_name AS butlerOwnerUserName, cc.company_type AS companyType, cc.is_verify_tax AS isVerifyTax, cc.is_bookkeeping AS isBookkeeping, cc.is_double_exemption AS isDoubleExemption, cc.create_time AS createTime FROM customer_company cc LEFT JOIN company_service cs on cs.company_id = cc.id LEFT JOIN customer_info ci on cs.customer_id = ci.id WHERE cs.deleted = 0
AND ( cc.company_name LIKE concat('%', #{params.key}, '%') OR cc.tax_number LIKE concat('%', #{params.key}, '%') OR ci.customer_name LIKE concat('%', #{params.key}, '%') OR ci.contact_name LIKE concat('%', #{params.key}, '%') OR ci.phone LIKE concat('%', #{params.key}, '%') OR ci.owner_user_name LIKE concat('%', #{params.key}, '%') OR cc.company_type LIKE concat('%', #{params.key}, '%') OR cc.is_verify_tax LIKE concat('%', #{params.key}, '%') OR cs.butler_owner_user_name LIKE concat('%', #{params.key}, '%') )
AND cc.company_name LIKE concat('%', #{params.companyName}, '%')
AND ci.customer_name LIKE concat('%', #{params.customerName}, '%')
AND ci.contact_name LIKE concat('%', #{params.contactName}, '%')
AND ci.phone LIKE concat('%', #{params.phone}, '%')
AND cc.company_type = #{params.companyType}
AND cs.butler_owner_user_name LIKE concat('%', #{params.butlerOwnerUserName}, '%')
AND cc.is_bookkeeping = #{params.isBookkeeping}
AND cc.is_double_exemption = #{params.isDoubleExemption}
AND EXISTS ( SELECT 1 FROM company_bank_statement_upload bsu WHERE bsu.company_id = cc.id AND bsu.period = #{params.statsPeriod} AND bsu.upload_count IS NOT NULL AND bsu.upload_count > 0 )
AND EXISTS ( SELECT 1 FROM company_bank_statement_upload bsu WHERE bsu.company_id = cc.id AND bsu.period = #{params.statsPeriod} AND bsu.no_statement = 1 AND (bsu.upload_count IS NULL OR bsu.upload_count = 0) )
AND NOT EXISTS ( SELECT 1 FROM company_bank_statement_upload bsu WHERE bsu.company_id = cc.id AND bsu.period = #{params.statsPeriod} AND ((bsu.upload_count IS NOT NULL AND bsu.upload_count > 0) OR bsu.no_statement = 1) )
and (cs.create_by in
#{item}
or cs.butler_owner_user in
#{item}
)
ORDER BY cc.create_time DESC

SELECT DISTINCT cc.id AS id, cc.company_name AS companyName, cs.butler_owner_user_name AS butlerOwnerUserName, ci.contact_name AS contactName, ci.phone AS phone, cc.create_time FROM customer_company cc LEFT JOIN company_service cs on cs.company_id = cc.id LEFT JOIN customer_info ci on cs.customer_id = ci.id WHERE cs.deleted = 0
AND cc.id = #{params.companyId}
AND cc.company_name LIKE concat('%', #{params.companyName}, '%')
AND cs.butler_owner_user_name LIKE concat('%', #{params.butlerOwnerUserName}, '%')
AND s1.follow_time >= #{params.start} AND s1.follow_time <= #{params.end}
and (cs.create_by in
#{item}
or cs.butler_owner_user in
#{item}
)
ORDER BY cc.create_time DESC

SELECT cc.id AS id, cs.id AS companyServiceId, cs.business_id AS businessId, cs.service_id AS serviceId, sm.service_name AS serviceName, cc.company_name AS companyName, cc.tax_number AS taxNumber, ci.customer_name AS customerName, ci.contact_name AS contactName, ci.phone AS phone, cs.butler_owner_user_name AS butlerOwnerUserName, cs.effective_date AS effectiveDate, cs.end_date AS endEate, cs.actual_end_date AS actualEndDate, cc.company_type AS companyType, cc.create_time AS createTime, lr.renew_type AS lastRenewType, lr.remark AS lastRenewRemark, lr.renew_amount AS lastRenewAmount, sc.id AS contractId, sc.contract_no AS contractNo, sc.contract_price AS contractPrice, (SELECT GROUP_CONCAT(p.product_name SEPARATOR '，') FROM contract_detail cd LEFT JOIN product_info p ON p.id = cd.product_id WHERE cd.contract_id = sc.id AND cd.deleted = 0) AS contractServices, wo.id AS workOrderId, wo.task_no AS workOrderTaskNo, wo.status AS workOrderStatus FROM customer_company cc LEFT JOIN company_service cs on cs.company_id = cc.id and cs.deleted = 0 LEFT JOIN customer_info ci on cs.customer_id = ci.id LEFT JOIN service_maintenance sm on sm.id = cs.service_id and sm.deleted = 0
LEFT JOIN ( SELECT company_service_id, MAX(id) AS max_renew_id FROM company_service_renew WHERE deleted = 0 GROUP BY company_service_id ) lr_max ON lr_max.company_service_id = cs.id LEFT JOIN company_service_renew lr ON lr.id = lr_max.max_renew_id LEFT JOIN contract sc on sc.id = cs.source_id and sc.deleted = 0 LEFT JOIN ( SELECT company_id, MAX(id) AS max_wo_id FROM work_order WHERE task_type = 'RENEWAL' AND status <> 'CANCELED' GROUP BY company_id ) wo_max ON wo_max.company_id = cc.id LEFT JOIN work_order wo ON wo.id = wo_max.max_wo_id WHERE cs.deleted = 0 AND (cc.company_status IS NULL OR cc.company_status NOT IN ('DEREGISTERED', 'CANCELLED'))
AND cc.id = #{params.companyId}
AND cc.company_name LIKE concat('%', #{params.companyName}, '%')
AND cc.company_type = #{params.companyType}
AND cs.butler_owner_user_name IN
#{item}
AND cs.actual_end_date BETWEEN #{params.start} AND #{params.end}
AND sm.service_name IN
#{item}
AND cs.actual_end_date < CURDATE()
AND cs.actual_end_date >= CURDATE() AND PERIOD_DIFF(DATE_FORMAT(cs.actual_end_date, '%Y%m'), DATE_FORMAT(CURDATE(), '%Y%m')) <= #{params.residueServiceIntervalMax}
and (cs.create_by in
#{item}
or cs.butler_owner_user in
#{item}
)
ORDER BY cc.create_time DESC

SELECT DATE_FORMAT(cs.actual_end_date, '%Y-%m') AS `month`, COUNT(*) AS serviceCount, COALESCE(SUM(sc.contract_price), 0) AS contractAmount FROM company_service cs LEFT JOIN contract sc ON sc.id = cs.source_id AND sc.deleted = 0 LEFT JOIN customer_company cc ON cc.id = cs.company_id AND cc.deleted = 0 LEFT JOIN service_maintenance sm ON sm.id = cs.service_id AND sm.deleted = 0 WHERE cs.deleted = 0 AND cs.actual_end_date BETWEEN #{start} AND #{end} AND (cc.company_status IS NULL OR cc.company_status NOT IN ('DEREGISTERED', 'CANCELLED')) AND (cs.status IS NULL OR cs.status <> 'CANCELLED')
AND cs.butler_owner_user_name IN #{b}
AND sm.service_name IN #{s}
GROUP BY DATE_FORMAT(cs.actual_end_date, '%Y-%m') ORDER BY `month`

SELECT cc.company_name AS companyName, cc.tax_number AS taxNumber, ci.contact_name AS contactName, ci.phone AS phone, cs.butler_owner_user_name AS butlerOwnerUserName, cs.effective_date AS effectiveDate, cs.actual_end_date AS actualEndDate FROM company_service cs LEFT JOIN customer_company cc ON cc.id = cs.company_id AND cc.deleted = 0 LEFT JOIN customer_info ci ON ci.id = cs.customer_id LEFT JOIN service_maintenance sm ON sm.id = cs.service_id AND sm.deleted = 0 WHERE cs.deleted = 0 AND cs.actual_end_date BETWEEN #{start} AND #{end} AND (cc.company_status IS NULL OR cc.company_status NOT IN ('DEREGISTERED', 'CANCELLED')) AND (cs.status IS NULL OR cs.status <> 'CANCELLED')
AND cs.butler_owner_user_name IN #{b}
AND sm.service_name IN #{s}
ORDER BY cc.company_name, cs.actual_end_date
